// Auto-generated for the Unit Board — 學測易混淆字 易混用法 (tools/confusables/build.py)
window.FD_DASHBOARD_UNITS = [{"unit":1,"theme":"almost / most / mostly；beside / besides；electric / electrical / electronic…","cards":[{"w":"almost","p":"adv.","d":"nearly","c":"幾乎","s":"Almost all the students passed the test.","t":"幾乎所有學生都通過考試。"},{"w":"most","p":"adj./pron.","d":"the largest number or amount","c":"大多數；最多","s":"Most people in Taiwan ride scooters to work.","t":"台灣大多數人騎機車上班。"},{"w":"mostly","p":"adv.","d":"mainly; usually","c":"大部分地；主要地","s":"The audience was mostly teenagers.","t":"觀眾大多是青少年。"},{"w":"beside","p":"prep.","d":"next to","c":"在…旁邊","s":"Come and sit beside me.","t":"過來坐我旁邊。"},{"w":"besides","p":"prep./adv.","d":"in addition to; also","c":"除…之外（還有）；此外","s":"Besides English, she also speaks French and Spanish.","t":"除了英文，她也會說法文和西班牙文。"},{"w":"electric","p":"adj.","d":"powered by electricity","c":"電動的；用電的","s":"More people are buying electric scooters to reduce pollution.","t":"越來越多人買電動機車以減少污染。"},{"w":"electrical","p":"adj.","d":"related to electricity","c":"電的；電氣的","s":"The fire was caused by an electrical problem in the kitchen.","t":"火災是廚房的電線問題引起的。"},{"w":"electronic","p":"adj.","d":"using computer chips or digital technology","c":"電子的","s":"Please turn off all electronic devices before the movie starts.","t":"電影開始前請關閉所有電子產品。"},{"w":"lend","p":"v.","d":"to let someone use something for a time","c":"借出","s":"Could you lend me your notes from yesterday's class?","t":"你能借我昨天上課的筆記嗎？"},{"w":"borrow","p":"v.","d":"to take something for a time and then return it","c":"借入","s":"Can I borrow your umbrella? I'll return it tomorrow.","t":"我可以借你的傘嗎？明天還你。"},{"w":"loan","p":"n./v.","d":"money borrowed from a bank","c":"貸款；借款","s":"They took out a loan to buy their first apartment.","t":"他們貸款買了第一間公寓。"},{"w":"advice","p":"n.","d":"an opinion about what someone should do","c":"建議；忠告","s":"My teacher gave me some useful advice about choosing a major.","t":"老師給了我一些選科系的實用建議。"},{"w":"advise","p":"v.","d":"to tell someone what you think they should do","c":"建議；勸告","s":"The doctor advised him to stop smoking.","t":"醫生勸他戒菸。"},{"w":"client","p":"n.","d":"a person who pays for a professional service","c":"委託人；客戶","s":"The lawyer met her client to discuss the case.","t":"律師和她的委託人討論案情。"},{"w":"customer","p":"n.","d":"a person who buys things from a shop","c":"顧客","s":"The shop gives free bags to its customers.","t":"這家店送顧客免費提袋。"},{"w":"guest","p":"n.","d":"a person invited to visit; a person staying at a hotel","c":"賓客；住客","s":"We have three guests staying with us this weekend.","t":"這週末有三位客人住在我們家。"},{"w":"passenger","p":"n.","d":"a person traveling in a car, bus, plane, or ship","c":"乘客","s":"All passengers must wear seat belts.","t":"所有乘客都必須繫安全帶。"},{"w":"efficient","p":"adj.","d":"working well without wasting time or energy","c":"有效率的","s":"An efficient worker finishes tasks quickly and correctly.","t":"有效率的員工能又快又正確地完成工作。"},{"w":"effective","p":"adj.","d":"producing the result you want","c":"有效的；生效的","s":"This medicine is very effective against headaches.","t":"這藥對頭痛非常有效。"},{"w":"farther","p":"adj./adv.","d":"at a greater distance","c":"更遠的；更遠地","s":"The hotel is farther from the station than I thought.","t":"飯店離車站比我想的還遠。"},{"w":"further","p":"adj./adv.","d":"more; additional","c":"更進一步的；額外的","s":"For further information, please visit our website.","t":"如需更多資訊，請上我們的網站。"},{"w":"historic","p":"adj.","d":"important in history","c":"有歷史意義的","s":"Landing on the moon was a historic event.","t":"登陸月球是具歷史意義的大事。"},{"w":"historical","p":"adj.","d":"related to the past or history","c":"歷史的；史學的","s":"She enjoys reading historical novels about the Tang dynasty.","t":"她喜歡讀以唐朝為背景的歷史小說。"},{"w":"journey","p":"n.","d":"a long trip from one place to another","c":"旅程；行程","s":"The journey from Taipei to Hualien takes about two hours by train.","t":"從台北到花蓮的火車行程約兩小時。"},{"w":"trip","p":"n.","d":"a short visit to a place","c":"旅行；出遊；出差","s":"We took a day trip to Jiufen last weekend.","t":"我們上週末去九份一日遊。"},{"w":"voyage","p":"n.","d":"a long trip by sea or in space","c":"航行；航程","s":"The ship's voyage across the Pacific took three weeks.","t":"這艘船橫越太平洋的航程花了三週。"},{"w":"tour","p":"n./v.","d":"a trip visiting several places","c":"遊覽；巡迴","s":"The guide gave us a tour of the old city.","t":"導遊帶我們遊覽古城。"}]},{"unit":2,"theme":"sensible / sensitive；accuse / blame / charge；injure / wound / damage…","cards":[{"w":"sensible","p":"adj.","d":"reasonable and practical","c":"明智的；合理的","s":"It is sensible to bring an umbrella in the rainy season.","t":"雨季帶把傘是明智之舉。"},{"w":"sensitive","p":"adj.","d":"easily hurt or affected; aware of others' feelings","c":"敏感的；體貼的","s":"My skin is sensitive to the sun, so I always wear sunscreen.","t":"我的皮膚對陽光很敏感，所以總是擦防曬。"},{"w":"accuse","p":"v.","d":"to say someone did something wrong (accuse sb of)","c":"指控；指責","s":"He was accused of stealing money from the shop.","t":"他被指控從店裡偷錢。"},{"w":"blame","p":"v./n.","d":"to say someone is responsible for something bad (blame sb for)","c":"責怪；歸咎","s":"Don't blame your brother for your own mistakes.","t":"別把你自己的錯怪到弟弟身上。"},{"w":"charge","p":"v.","d":"to officially accuse someone of a crime (charge sb with)","c":"控告；起訴","s":"The driver was charged with drunk driving.","t":"這名駕駛被以酒駕起訴。"},{"w":"injure","p":"v.","d":"to hurt someone, especially in an accident","c":"使受傷","s":"Three people were injured in the car accident.","t":"三人在車禍中受傷。"},{"w":"wound","p":"n./v.","d":"an injury made by a knife or gun","c":"傷口；（武器）使受傷","s":"The soldier was wounded in the leg during the battle.","t":"這名士兵在戰鬥中腿部受傷。"},{"w":"damage","p":"v./n.","d":"to harm a thing","c":"損壞；損害","s":"The typhoon damaged many houses along the coast.","t":"颱風損壞沿海許多房屋。"},{"w":"remind","p":"v.","d":"to make someone remember something","c":"提醒；使想起","s":"Please remind me to buy milk on the way home.","t":"請提醒我回家路上買牛奶。"},{"w":"remember","p":"v.","d":"to keep something in your memory","c":"記得","s":"Do you remember the name of our first-grade teacher?","t":"你記得我們一年級老師的名字嗎？"},{"w":"recall","p":"v.","d":"to bring a past event back into your mind","c":"回想起；回憶","s":"I can't recall where I put my keys.","t":"我想不起來把鑰匙放哪了。"},{"w":"rise","p":"v.","d":"to go up","c":"上升；升起","s":"The sun rises in the east.","t":"太陽從東方升起。"},{"w":"raise","p":"v.","d":"to lift; to increase; to bring up children","c":"舉起；提高；養育","s":"If you know the answer, raise your hand.","t":"知道答案的人請舉手。"},{"w":"arise","p":"v.","d":"(of a problem) to happen","c":"（問題）出現；發生","s":"Call me if any problems arise while I'm away.","t":"我不在時如果有任何問題發生，請打給我。"},{"w":"arouse","p":"v.","d":"to cause a feeling or interest","c":"喚起；引起","s":"The strange box aroused the children's curiosity.","t":"那個奇怪的盒子引起孩子們的好奇心。"},{"w":"salary","p":"n.","d":"fixed money paid every month for a job","c":"薪水（月薪）","s":"Her monthly salary is enough to pay the rent and save a little.","t":"她的月薪足以付房租並存一點錢。"},{"w":"wage","p":"n.","d":"money paid by the hour or week","c":"工資","s":"Part-time workers earn an hourly wage.","t":"兼職人員領時薪。"},{"w":"fare","p":"n.","d":"money paid for a trip by bus, train, or plane","c":"車資；票價","s":"Children pay half the fare on this bus.","t":"搭這班公車兒童付半價。"},{"w":"fee","p":"n.","d":"money paid for a service","c":"費用（學費、手續費）","s":"There is a small fee for using the swimming pool.","t":"使用游泳池要付少許費用。"},{"w":"alone","p":"adj./adv.","d":"without other people","c":"單獨的；獨自","s":"She likes to travel alone.","t":"她喜歡一個人旅行。"},{"w":"lonely","p":"adj.","d":"sad because you are alone","c":"寂寞的；孤單的","s":"The old man felt lonely after his children moved away.","t":"孩子們搬走後老人感到很寂寞。"},{"w":"lonesome","p":"adj.","d":"(AmE) lonely; far from people","c":"寂寞的；人煙稀少的","s":"The farmhouse stood on a lonesome road far from town.","t":"農舍坐落在一條遠離市鎮、人煙稀少的路旁。"},{"w":"rob","p":"v.","d":"to take money or things from a person or place, often by force","c":"搶劫","s":"Two men robbed the bank and escaped in a car.","t":"兩名男子搶劫銀行後開車逃逸。"},{"w":"steal","p":"v.","d":"to take something secretly without permission","c":"偷","s":"Someone tried to steal my wallet on the crowded bus.","t":"有人想在擁擠的公車上偷我的錢包。"},{"w":"award","p":"n./v.","d":"a prize given for doing something well","c":"獎；頒發","s":"She won an award for best actress.","t":"她獲得最佳女主角獎。"},{"w":"reward","p":"n./v.","d":"something given in return for good work or help","c":"報酬；獎賞；酬謝","s":"The family offered a reward to anyone who found their lost dog.","t":"這家人懸賞找回走失的狗。"},{"w":"canal","p":"n.","d":"a man-made river for boats or water","c":"運河","s":"Venice is famous for its canals and boats.","t":"威尼斯以運河和船聞名。"},{"w":"channel","p":"n.","d":"a TV station; a passage of water; a way of communicating","c":"頻道；海峽；管道","s":"Which channel is the baseball game on?","t":"棒球比賽在哪一台播？"}]},{"unit":3,"theme":"convince / persuade；intellectual / intelligent；shade / shadow…","cards":[{"w":"convince","p":"v.","d":"to make someone believe something is true","c":"使相信；使信服","s":"The evidence convinced the police that he was telling the truth.","t":"證據讓警方相信他說的是實話。"},{"w":"persuade","p":"v.","d":"to make someone agree to do something","c":"說服","s":"She persuaded her father to buy a new computer.","t":"她說服爸爸買一台新電腦。"},{"w":"intelligent","p":"adj.","d":"able to learn and understand quickly","c":"聰明的；有智慧的","s":"Dolphins are very intelligent animals.","t":"海豚是非常聰明的動物。"},{"w":"intellectual","p":"adj./n.","d":"related to the mind and thinking; a person who thinks deeply","c":"智力的；知識分子","s":"Reading helps children's intellectual development.","t":"閱讀有助孩子的智力發展。"},{"w":"shade","p":"n.","d":"an area that is cool and dark because the sun is blocked","c":"陰涼處；樹蔭","s":"Let's sit in the shade of that big tree.","t":"我們坐到那棵大樹的樹蔭下吧。"},{"w":"shadow","p":"n.","d":"the dark shape made when something blocks light","c":"影子；陰影","s":"In the evening, our shadows became very long.","t":"傍晚時我們的影子變得很長。"},{"w":"sometime","p":"adv.","d":"at a time that is not known or decided","c":"某個時候","s":"Let's have lunch together sometime next week.","t":"下週找個時間一起吃午餐吧。"},{"w":"sometimes","p":"adv.","d":"on some occasions but not always","c":"有時候","s":"I sometimes walk to school when the weather is nice.","t":"天氣好時我有時走路上學。"},{"w":"some time","p":"n.phr.","d":"a period of time","c":"一段時間","s":"It will take some time to get used to the new school.","t":"適應新學校需要一段時間。"},{"w":"successful","p":"adj.","d":"achieving what you want","c":"成功的","s":"She is a successful businesswoman who owns three restaurants.","t":"她是一位擁有三家餐廳的成功女企業家。"},{"w":"successive","p":"adj.","d":"following one after another","c":"連續的；相繼的","s":"The team has won the title for three successive years.","t":"這支隊伍連續三年奪冠。"},{"w":"custom","p":"n.","d":"a traditional way of doing something","c":"習俗；風俗","s":"It's a custom to give red envelopes during Chinese New Year.","t":"過年發紅包是一種習俗。"},{"w":"customs","p":"n.","d":"the place at a border where bags are checked","c":"海關","s":"We had to open our suitcases at customs.","t":"我們在海關必須打開行李箱。"},{"w":"costume","p":"n.","d":"clothes worn by actors or for special events","c":"戲服；（特殊）服裝","s":"My little sister wore a tiger costume to the Halloween party at school.","t":"我妹妹穿著老虎裝參加學校的萬聖節派對。"},{"w":"rent","p":"v./n.","d":"to pay money to use a house or car; the money paid","c":"租；租金","s":"We rented a car for our trip around the island.","t":"我們租了一輛車環島旅行。"},{"w":"hire","p":"v.","d":"to employ someone","c":"雇用","s":"The café hired two students to work on weekends.","t":"這家咖啡廳雇用了兩名學生週末打工。"},{"w":"lease","p":"n./v.","d":"a legal agreement to rent something for a long time","c":"租約；租賃","s":"The shop signed a five-year lease on the building.","t":"這家店簽下這棟樓的五年租約。"},{"w":"glance","p":"v./n.","d":"to look quickly","c":"瞥一眼；匆匆一看","s":"She glanced at her watch and hurried out.","t":"她瞥了一眼手錶就匆匆出門。"},{"w":"glimpse","p":"n./v.","d":"a brief, incomplete view","c":"一瞥；瞥見","s":"We caught a glimpse of the singer as she got into her car.","t":"歌手上車時我們瞥見了她。"},{"w":"gaze","p":"v./n.","d":"to look at something for a long time, often with interest","c":"凝視","s":"He sat by the window, gazing at the stars.","t":"他坐在窗邊凝視著星星。"},{"w":"stare","p":"v./n.","d":"to look at something for a long time without moving your eyes","c":"盯著看；瞪","s":"It's rude to stare at people on the train.","t":"在火車上盯著別人看很沒禮貌。"},{"w":"glare","p":"v./n.","d":"to look at someone angrily; strong light","c":"怒視；強光","s":"The teacher glared at the students who were talking.","t":"老師怒視那些講話的學生。"},{"w":"considerable","p":"adj.","d":"large in size or amount","c":"相當大的；可觀的","s":"The new road cost a considerable amount of money.","t":"新道路花了相當可觀的經費。"},{"w":"considerate","p":"adj.","d":"thinking about other people's feelings","c":"體貼的","s":"It was considerate of you to turn down the music while I was studying.","t":"你在我讀書時把音樂關小聲，真體貼。"},{"w":"continual","p":"adj.","d":"happening often, again and again","c":"不斷反覆的；頻繁的","s":"I'm tired of his continual complaints about the food.","t":"我受夠了他對食物一再的抱怨。"},{"w":"continuous","p":"adj.","d":"without stopping","c":"連續不斷的","s":"The machine makes a continuous noise all day.","t":"這台機器整天發出不間斷的噪音。"}]},{"unit":4,"theme":"device / devise；economic / economical；envious / jealous…","cards":[{"w":"device","p":"n.","d":"a machine or tool made for a purpose","c":"裝置；設備","s":"Please turn off all electronic devices during the exam.","t":"考試時請關閉所有電子裝置。"},{"w":"devise","p":"v.","d":"to think of a new plan or method","c":"設計；想出","s":"The students devised a way to collect rainwater for the school garden.","t":"學生們想出收集雨水灌溉校園菜園的方法。"},{"w":"economic","p":"adj.","d":"related to the economy","c":"經濟的","s":"The country has had strong economic growth this year.","t":"這個國家今年經濟成長強勁。"},{"w":"economical","p":"adj.","d":"using little money or fuel","c":"節省的；划算的","s":"Buying a big bag of rice is more economical than buying small ones.","t":"買大包米比買小包划算。"},{"w":"envious","p":"adj.","d":"wanting something that another person has","c":"羨慕的","s":"I'm envious of my sister because she can travel to Japan every year.","t":"我很羨慕姊姊每年都能去日本旅行。"},{"w":"jealous","p":"adj.","d":"unhappy because someone may take what you have; envious","c":"嫉妒的；吃醋的","s":"He gets jealous when his girlfriend talks to other boys.","t":"女友和其他男生說話時，他就會吃醋。"},{"w":"expand","p":"v.","d":"to become larger in size or amount","c":"擴大；擴張","s":"The company plans to expand into Japan next year.","t":"這家公司計畫明年擴展到日本。"},{"w":"extend","p":"v.","d":"to make longer; to reach; to offer","c":"延長；延伸；給予","s":"The teacher extended the deadline by three days.","t":"老師把截止日延長了三天。"},{"w":"intense","p":"adj.","d":"very strong or serious","c":"強烈的；激烈的","s":"There is intense competition for places at top universities.","t":"頂尖大學的名額競爭激烈。"},{"w":"intensive","p":"adj.","d":"involving a lot of work in a short time","c":"密集的；加強的","s":"I took an intensive English course during the summer.","t":"我暑假上了一門密集英文課。"},{"w":"prevent","p":"v.","d":"to stop something from happening","c":"預防；阻止","s":"Washing your hands can prevent the spread of disease.","t":"洗手可以預防疾病傳播。"},{"w":"forbid","p":"v.","d":"to order someone not to do something","c":"禁止","s":"My parents forbid me to play video games on school nights.","t":"我爸媽禁止我在上學日的晚上打電動。"},{"w":"prohibit","p":"v.","d":"to officially ban by law or rule","c":"（法規）禁止","s":"The law prohibits people under eighteen from buying cigarettes.","t":"法律禁止未滿十八歲者購買香菸。"},{"w":"ashamed","p":"adj.","d":"feeling bad because you did something wrong","c":"感到羞愧的","s":"He was ashamed of lying to his parents.","t":"他對自己騙了父母感到羞愧。"},{"w":"shameful","p":"adj.","d":"so bad that people should feel shame","c":"可恥的","s":"Cheating on a test is shameful behavior.","t":"考試作弊是可恥的行為。"},{"w":"worth","p":"adj./prep.","d":"having a certain value; good enough to do","c":"值…；值得","s":"This museum is worth visiting if you like history.","t":"如果你喜歡歷史，這間博物館值得一去。"},{"w":"worthy","p":"adj.","d":"deserving respect or attention (worthy of)","c":"值得的；配得上的","s":"Her idea is worthy of serious discussion.","t":"她的想法值得認真討論。"},{"w":"worthwhile","p":"adj.","d":"worth the time, money, or effort","c":"值得（花時間精力）的","s":"Volunteering at the hospital was a worthwhile experience.","t":"在醫院當志工是很值得的經驗。"},{"w":"audience","p":"n.","d":"the people watching or listening to a performance","c":"聽眾；觀眾","s":"The audience clapped loudly at the end of the concert.","t":"演唱會結束時觀眾熱烈鼓掌。"},{"w":"spectator","p":"n.","d":"a person watching a sports event","c":"（比賽）觀眾","s":"Thousands of spectators filled the stadium for the final.","t":"數千名觀眾湧入體育場觀看決賽。"},{"w":"viewer","p":"n.","d":"a person watching TV or online videos","c":"（電視、網路）觀眾","s":"The show has more than one million viewers every week.","t":"這節目每週有超過一百萬名觀眾。"},{"w":"alternate","p":"adj./v.","d":"happening in turns; every other one","c":"交替的；輪流","s":"We take turns cleaning the room on alternate days.","t":"我們隔天輪流打掃房間。"},{"w":"alternative","p":"n./adj.","d":"another possible choice","c":"替代方案；可替代的","s":"If the bus is full, the MRT is a good alternative.","t":"如果公車客滿，搭捷運是不錯的替代方案。"}]},{"unit":5,"theme":"comprise / compose；council / counsel；respectable / respectful / respective…","cards":[{"w":"comprise","p":"v.","d":"to consist of; to be made up of","c":"由…組成；包含","s":"The committee comprises five teachers and two students.","t":"委員會由五位老師和兩名學生組成。"},{"w":"compose","p":"v.","d":"to form a whole; to write music or a poem","c":"組成；作（曲）","s":"Water is composed of hydrogen and oxygen.","t":"水是由氫和氧組成的。"},{"w":"council","p":"n.","d":"a group of people chosen to make decisions","c":"議會；委員會","s":"The city council voted to build a new library.","t":"市議會投票通過興建新圖書館。"},{"w":"counsel","p":"v./n.","d":"to give advice","c":"勸告；諮商；忠告","s":"Teachers counsel students who are worried about choosing a university.","t":"老師為擔心選大學的學生提供諮商。"},{"w":"respectable","p":"adj.","d":"considered good or proper by society","c":"體面的；值得尊敬的","s":"He wore a suit to look respectable at the interview.","t":"他穿西裝去面試，看起來很體面。"},{"w":"respectful","p":"adj.","d":"showing respect","c":"尊敬的；有禮貌的","s":"Be respectful to the elderly.","t":"對長者要有禮貌。"},{"w":"respective","p":"adj.","d":"belonging to each one separately","c":"各自的","s":"After the party, the guests went back to their respective homes.","t":"派對結束後，客人們各自回家。"},{"w":"industrial","p":"adj.","d":"related to industry and factories","c":"工業的；產業的","s":"Kaohsiung is a major industrial city in southern Taiwan.","t":"高雄是台灣南部的重要工業城市。"},{"w":"industrious","p":"adj.","d":"working hard","c":"勤勉的；勤奮的","s":"The industrious student studies in the library every evening.","t":"這位勤奮的學生每晚都在圖書館讀書。"},{"w":"ensure","p":"v.","d":"to make certain that something happens","c":"確保","s":"Please check your answers to ensure there are no mistakes.","t":"請檢查答案以確保沒有錯誤。"},{"w":"insure","p":"v.","d":"to buy insurance for something","c":"為…投保","s":"We insured our house against fire and earthquakes.","t":"我們為房子投保了火險和地震險。"},{"w":"assure","p":"v.","d":"to tell someone confidently that something is true","c":"向…保證","s":"The doctor assured me that the operation was safe.","t":"醫生向我保證手術很安全。"},{"w":"imaginary","p":"adj.","d":"existing only in the mind","c":"想像中的；虛構的","s":"My little brother has an imaginary friend named Bobo.","t":"我弟弟有一個叫波波的想像中的朋友。"},{"w":"imaginative","p":"adj.","d":"having new and creative ideas","c":"富有想像力的","s":"The imaginative design of the library attracts many visitors.","t":"這座圖書館富有想像力的設計吸引許多遊客。"},{"w":"imaginable","p":"adj.","d":"possible to imagine","c":"可想像得到的","s":"The shop sells ice cream in every flavor imaginable.","t":"這家店賣你想像得到的各種口味冰淇淋。"},{"w":"emigrate","p":"v.","d":"to leave your country to live in another","c":"移居國外","s":"Her grandparents emigrated from Taiwan to Canada in 1980.","t":"她的祖父母在 1980 年從台灣移居加拿大。"},{"w":"immigrate","p":"v.","d":"to come into a country to live there","c":"移入（某國）","s":"Many workers immigrate to Taiwan from Southeast Asia.","t":"許多勞工從東南亞移入台灣。"},{"w":"migration","p":"n.","d":"the movement of animals or people from one place to another","c":"遷徙；移居","s":"Every winter, the migration of birds brings visitors to the wetlands.","t":"每年冬天，候鳥遷徙吸引遊客前往濕地。"},{"w":"imply","p":"v.","d":"to suggest something without saying it directly","c":"暗示；意味著","s":"Her silence implied that she did not agree.","t":"她的沉默暗示她不同意。"},{"w":"infer","p":"v.","d":"to form an opinion from facts","c":"推論；推斷","s":"From his tired face, I inferred that he hadn't slept well.","t":"從他疲倦的臉，我推斷他沒睡好。"},{"w":"interfere","p":"v.","d":"to get involved when not wanted; to get in the way","c":"干涉；妨礙","s":"Don't let your phone interfere with your sleep.","t":"別讓手機妨礙你的睡眠。"},{"w":"intervene","p":"v.","d":"to step in to stop or improve a situation","c":"介入；調停","s":"The teacher intervened before the argument became a fight.","t":"老師在爭吵演變成打架前介入。"},{"w":"objective","p":"adj./n.","d":"based on facts, not feelings; a goal","c":"客觀的；目標","s":"A judge must be objective and not take sides.","t":"法官必須客觀，不能偏袒任何一方。"},{"w":"subjective","p":"adj.","d":"based on personal feelings or opinions","c":"主觀的","s":"Whether a movie is good or bad is often subjective.","t":"電影好不好看往往很主觀。"}]},{"unit":6,"theme":"precede / proceed；complement / compliment；explicit / implicit…","cards":[{"w":"precede","p":"v.","d":"to come before something","c":"在…之前","s":"Heavy rain preceded the typhoon.","t":"颱風來臨前先下了大雨。"},{"w":"proceed","p":"v.","d":"to continue; to go forward","c":"繼續進行；前往","s":"After a short break, we proceeded with the meeting.","t":"短暫休息後，我們繼續開會。"},{"w":"complement","p":"v./n.","d":"to go well with something; to make it complete","c":"補足；與…相配","s":"The red wine complements the beef perfectly.","t":"紅酒和牛肉搭配得恰到好處。"},{"w":"compliment","p":"n./v.","d":"something nice you say about someone","c":"稱讚；恭維","s":"She received many compliments on her new haircut.","t":"她的新髮型得到很多稱讚。"},{"w":"explicit","p":"adj.","d":"clear and direct","c":"明確的；清楚的","s":"The teacher gave explicit instructions about how to write the report.","t":"老師對報告的寫法給了明確的指示。"},{"w":"implicit","p":"adj.","d":"suggested but not said directly","c":"含蓄的；暗示的","s":"There was an implicit agreement that we would share the cost.","t":"我們心照不宣地同意分攤費用。"},{"w":"breakthrough","p":"n.","d":"an important new discovery","c":"突破","s":"Scientists made a breakthrough in the treatment of cancer.","t":"科學家在癌症治療上取得突破。"},{"w":"breakdown","p":"n.","d":"a failure of a machine; a sudden loss of mental health","c":"故障；崩潰","s":"Our car had a breakdown on the highway.","t":"我們的車在高速公路上拋錨。"},{"w":"breakup","p":"n.","d":"the end of a relationship or group","c":"分手；解散","s":"She was sad for weeks after the breakup.","t":"分手後她難過了好幾週。"},{"w":"adverse","p":"adj.","d":"harmful or unfavorable","c":"不利的；有害的","s":"The medicine may have adverse effects, such as headaches.","t":"這藥可能有頭痛等不良影響。"},{"w":"averse","p":"adj.","d":"strongly disliking (averse to)","c":"反對的；不喜歡的","s":"He is not averse to hard work if the pay is fair.","t":"只要薪水合理，他並不排斥辛苦工作。"},{"w":"discreet","p":"adj.","d":"careful about what you say or do, to keep secrets","c":"謹慎的；低調的","s":"Please be discreet; nobody else knows about the surprise party.","t":"請保密，其他人都不知道這個驚喜派對。"},{"w":"discrete","p":"adj.","d":"separate and different","c":"分離的；個別的","s":"The course is divided into five discrete units.","t":"這門課分成五個獨立的單元。"}]}];
